fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    let len = a.len();
    // Since both arrays have equal length, no need for out-of-bounds checks.
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        result.push(a[i] & b[i]);
    }

    result
}